     1→import { BottomSheetModal, BottomSheetScrollView } from "@gorhom/bottom-sheet";
     2→import {
     3→  animateSequence,
     4→  Block,
     5→  Text,
     6→  useAndroidBackHandler,
     7→} from "@prototyp/skeletor";
     8→import { MembershipState_Tags } from "@unomed/react-native-matrix-sdk";
     9→import { MatrixService } from "modules/matrix-client/services";
    10→import { NavigationContainerRef } from "modules/navigation/const";
    11→import { useCallback, useEffect, useMemo, useRef, useState } from "react";
    12→import { Alert, Dimensions, Image, StyleSheet } from "react-native";
    13→import Toast from "react-native-toast-message";
    14→import { Button, Loading } from "shared/components";
    15→import { UserImage } from "shared/components/user-image/UserImage";
    16→import { usePreventSwipeBack } from "shared/hooks";
    17→import { Colors, TextSize } from "shared/styles";
    18→
    19→const { height } = Dimensions.get("screen");
    20→
    21→interface Props {
    22→  isBottomSheetOpen: boolean;
    23→  selectedMember: MemberDetailsPayload | null;
    24→  roomId: string;
    25→  onClose: () => void;
    26→}
    27→
    28→export const MemberDetailsBottomSheet: React.FC<Props> = ({
    29→  isBottomSheetOpen,
    30→  selectedMember,
    31→  roomId,
    32→  onClose,
    33→}) => {
    34→  const ref = useRef<BottomSheetModal>(null);
    35→  const fadeIn = useRef(
    36→    animateSequence(
    37→      { opacity: [0, 1] },
    38→      {
    39→        duration: 200,
    40→      },
    41→    ),
    42→  ).current;
    43→  const [userPowerLevel, setUserPowerLevel] = useState<number | null>(null);
    44→  const [memberPowerLevel, setMemberPowerLevel] = useState<number | null>(null);
    45→  const isAdmin = useMemo(() => userPowerLevel === 100, [userPowerLevel]);
    46→  const isMemberAdmin = useMemo(
    47→    () => memberPowerLevel === 100,
    48→    [memberPowerLevel],
    49→  );
    50→  const isUser = useMemo(
    51→    () => selectedMember?.userId === MatrixService.instance?.userId(),
    52→    [selectedMember],
    53→  );
    54→  const isBanned = useMemo(
    55→    () => selectedMember?.membershipTag === MembershipState_Tags.Ban,
    56→    [selectedMember],
    57→  );
    58→  const [activeAction, setActiveAction] = useState<
    59→    "remove" | "ban" | "unban" | null
    60→  >(null);
    61→
    62→  const handleCloseBottomSheet = useCallback(() => {
    63→    fadeIn.reverse(() => onClose());
    64→  }, [fadeIn, onClose]);
    65→
    66→  const handleCloseBottomSheetOnPress = useCallback(() => {
    67→    handleCloseBottomSheet();
    68→    ref.current?.close();
    69→  }, [handleCloseBottomSheet]);
    70→
    71→  const handleViewProfile = useCallback(() => {
    72→    ref.current?.close();
    73→
    74→    if (isUser) {
    75→      NavigationContainerRef.navigate("userProfile");
    76→      return;
    77→    }
    78→    if (!selectedMember) return;
    79→
    80→    NavigationContainerRef.navigate("profile", {
    81→      userId: selectedMember.userId,
    82→    });
    83→  }, [isUser, selectedMember]);
    84→
    85→  const handleConfirmAction = useCallback(
    86→    async (action: "remove" | "ban" | "unban", reason: string) => {
    87→      if (!selectedMember) return;
    88→      try {
    89→        setActiveAction(action);
    90→        handleCloseBottomSheet();
    91→        ref.current?.close();
    92→
    93→        if (action === "ban") {
    94→          await MatrixService.banUserFromRoom(
    95→            roomId,
    96→            selectedMember.userId,
    97→            reason || undefined,
    98→          );
    99→        } else if (action === "unban") {
   100→          await MatrixService.unbanUserFromRoom(
   101→            roomId,
   102→            selectedMember.userId,
   103→            reason || undefined,
   104→          );
   105→        } else {
   106→          await MatrixService.removeUserFromRoom(
   107→            roomId,
   108→            selectedMember.userId,
   109→            reason || undefined,
   110→          );
   111→        }
   112→
   113→        Toast.show({
   114→          type: "success",
   115→          text1: `User ${action === "ban" ? "banned" : action === "unban" ? "unbanned" : "removed"} successfully`,
   116→        });
   117→        NavigationContainerRef.goBack();
   118→      } catch (error) {
   119→        console.error(`Failed to ${action} user:`, error);
   120→        Toast.show({
   121→          type: "error",
   122→          text1: `Failed to ${action} user`,
   123→        });
   124→      } finally {
   125→        setActiveAction(null);
   126→      }
   127→    },
   128→    [selectedMember, roomId, handleCloseBottomSheet],
   129→  );
   130→
   131→  const handleUserAction = useCallback(
   132→    (action: "remove" | "ban" | "unban") => {
   133→      if (!selectedMember) return;
   134→
   135→      const actionText = action === "ban" ? "banning" : "removing";
   136→      const actionTitle = action === "ban" ? "Ban User" : "Remove User";
   137→      const confirmButtonText =
   138→        action === "ban" ? "Ban" : action === "unban" ? "Unban" : "Remove";
   139→
   140→      if (action === "unban") {
   141→        Alert.alert(
   142→          "Unban User",
   143→          `Are you sure you want to unban ${selectedMember.displayName}?`,
   144→          [
   145→            {
   146→              text: "Cancel",
   147→              style: "cancel",
   148→            },
   149→            {
   150→              text: "Unban",
   151→              onPress: () => handleConfirmAction("unban", ""),
   152→            },
   153→          ],
   154→        );
   155→        return;
   156→      }
   157→
   158→      Alert.prompt(
   159→        actionTitle,
   160→        `Enter a reason for ${actionText} ${selectedMember.displayName} (optional):`,
   161→        [
   162→          {
   163→            text: "Cancel",
   164→            style: "cancel",
   165→          },
   166→          {
   167→            text: "Continue",
   168→            onPress: (reason?: string) => {
   169→              Alert.alert(
   170→                "Are you sure?",
   171→                `Are you sure you want to ${action} ${selectedMember.displayName} from this room?`,
   172→                [
   173→                  {
   174→                    text: "Cancel",
   175→                    style: "cancel",
   176→                  },
   177→                  {
   178→                    text: confirmButtonText,
   179→                    style: "destructive",
   180→                    onPress: () => handleConfirmAction(action, reason || ""),
   181→                  },
   182→                ],
   183→              );
   184→            },
   185→          },
   186→        ],
   187→        "plain-text",
   188→      );
   189→    },
   190→    [selectedMember, handleConfirmAction],
   191→  );
   192→
   193→  const handleRemoveUser = useCallback(
   194→    () => handleUserAction("remove"),
   195→    [handleUserAction],
   196→  );
   197→
   198→  const handleBanUser = useCallback(
   199→    () => handleUserAction("ban"),
   200→    [handleUserAction],
   201→  );
   202→
   203→  const handleUnbanUser = useCallback(
   204→    () => handleUserAction("unban"),
   205→    [handleUserAction],
   206→  );
   207→
   208→  useAndroidBackHandler({
   209→    handlePress: handleCloseBottomSheetOnPress,
   210→    enabled: isBottomSheetOpen,
   211→    disableDefault: isBottomSheetOpen,
   212→  });
   213→
   214→  usePreventSwipeBack(isBottomSheetOpen);
   215→
   216→  useEffect(() => {
   217→    if (!isBottomSheetOpen || !selectedMember) return;
   218→    MatrixService.getUserPowerLevel(roomId)
   219→      .then(setUserPowerLevel)
   220→      .catch(console.error);
   221→    MatrixService.getUserPowerLevel(roomId, selectedMember.userId)
   222→      .then(setMemberPowerLevel)
   223→      .catch(console.error);
   224→  }, [isBottomSheetOpen, selectedMember]);
   225→
   226→  useEffect(() => {
   227→    if (!isBottomSheetOpen) return;
   228→
   229→    fadeIn.start();
   230→    ref.current?.present();
   231→  }, [isBottomSheetOpen, fadeIn]);
   232→
   233→  if (!isBottomSheetOpen || !selectedMember) return null;
   234→
   235→  return (
   236→    <>
   237→      {activeAction && (
   238→        <Loading
   239→          text={
   240→            activeAction === "ban"
   241→              ? "Banning user..."
   242→              : activeAction === "unban"
   243→                ? "Unbanning user..."
   244→                : "Removing user..."
   245→          }
   246→        />
   247→      )}
   248→      <Block
   249→        absolute
   250→        width="100%"
   251→        height="100%"
   252→        offsets={{ left: 0, bottom: 0 }}
   253→        animations={fadeIn.animations}
   254→        zIndex={9999}
   255→        background={Colors.black70}
   256→      >
   257→        <BottomSheetModal
   258→          ref={ref}
   259→          handleStyle={styles.handle}
   260→          handleIndicatorStyle={styles.handleIndicator}
   261→          backgroundStyle={styles.background}
   262→          enablePanDownToClose
   263→          enableDynamicSizing
   264→          maxDynamicContentSize={height - 200}
   265→          onDismiss={handleCloseBottomSheet}
   266→          enableContentPanningGesture={false}
   267→        >
   268→          <BottomSheetScrollView scrollEnabled={false}>
   269→            <Block
   270→              justify="space-between"
   271→              flexDirection="column"
   272→              flex={1}
   273→              width="100%"
   274→              gap={16}
   275→              paddings={{
   276→                paddingHorizontal: 20,
   277→                paddingBottom: 56,
   278→              }}
   279→            >
   280→              <Block align="center" gap={16} margins={{ marginBottom: 60 }}>
   281→                <UserImage
   282→                  avatarUrl={selectedMember.avatarUrl}
   283→                  displayName={selectedMember.displayName}
   284→                  width={120}
   285→                  height={120}
   286→                  borderRadius={999}
   287→                />
   288→                <Block align="center" gap={4}>
   289→                  <Text
   290→                    size={TextSize.large}
   291→                    color={Colors.white}
   292→                    font="InstrumentSans-Bold"
   293→                  >
   294→                    {selectedMember.displayName}
   295→                  </Text>
   296→                  <Text color={Colors.white50} font="InstrumentSans-Regular">
   297→                    {selectedMember.userId}
   298→                  </Text>
   299→                </Block>
   300→              </Block>
   301→              <Block gap={20}>
   302→                <Button.Wrapper onPress={handleViewProfile}>
   303→                  <Block
   304→                    width="100%"
   305→                    flexDirection="row"
   306→                    align="center"
   307→                    gap={12}
   308→                    paddings={{ paddingBottom: 20 }}
   309→                    border={{
   310→                      borderBottomWidth: 1,
   311→                      borderColor: Colors.white5,
   312→                    }}
   313→                  >
   314→                    <Image
   315→                      source={require("assets/icons/user.png")}
   316→                      style={styles.icon}
   317→                    />
   318→                    <Text color={Colors.white}>View Profile</Text>
   319→                  </Block>
   320→                </Button.Wrapper>
   321→                {isAdmin && !isUser && !isBanned && (
   322→                  <Button.Wrapper
   323→                    onPress={handleRemoveUser}
   324→                    disabled={isMemberAdmin}
   325→                  >
   326→                    <Block
   327→                      width="100%"
   328→                      flexDirection="row"
   329→                      align="center"
   330→                      gap={12}
   331→                      paddings={{ paddingBottom: 20 }}
   332→                      border={{
   333→                        borderBottomWidth: 1,
   334→                        borderColor: Colors.white5,
   335→                      }}
   336→                    >
   337→                      <Image
   338→                        source={require("assets/icons/close.png")}
   339→                        style={styles.icon}
   340→                      />
   341→                      <Text color={Colors.white}>Remove user</Text>
   342→                    </Block>
   343→                  </Button.Wrapper>
   344→                )}
   345→                {isAdmin && !isUser && !isBanned && (
   346→                  <Button.Wrapper
   347→                    onPress={handleBanUser}
   348→                    disabled={isMemberAdmin}
   349→                  >
   350→                    <Block
   351→                      width="100%"
   352→                      flexDirection="row"
   353→                      align="center"
   354→                      gap={12}
   355→                      paddings={{ paddingBottom: 20 }}
   356→                      border={{
   357→                        borderBottomWidth: 1,
   358→                        borderColor: Colors.white5,
   359→                      }}
   360→                    >
   361→                      <Image
   362→                        source={require("assets/icons/ban.png")}
   363→                        style={styles.icon}
   364→                      />
   365→                      <Text color={Colors.white}>Ban user</Text>
   366→                    </Block>
   367→                  </Button.Wrapper>
   368→                )}
   369→                {isAdmin && !isUser && isBanned && (
   370→                  <Button.Wrapper onPress={handleUnbanUser}>
   371→                    <Block
   372→                      width="100%"
   373→                      flexDirection="row"
   374→                      align="center"
   375→                      gap={12}
   376→                      paddings={{ paddingBottom: 20 }}
   377→                      border={{
   378→                        borderBottomWidth: 1,
   379→                        borderColor: Colors.white5,
   380→                      }}
   381→                    >
   382→                      <Image
   383→                        source={require("assets/icons/ban.png")}
   384→                        style={styles.icon}
   385→                      />
   386→                      <Text color={Colors.white}>Unban user</Text>
   387→                    </Block>
   388→                  </Button.Wrapper>
   389→                )}
   390→              </Block>
   391→            </Block>
   392→          </BottomSheetScrollView>
   393→        </BottomSheetModal>
   394→      </Block>
   395→    </>
   396→  );
   397→};
   398→
   399→const styles = StyleSheet.create({
   400→  background: {
   401→    backgroundColor: Colors.blackMinus1,
   402→    borderTopLeftRadius: 24,
   403→    borderTopRightRadius: 24,
   404→    paddingHorizontal: 24,
   405→  },
   406→  handle: {
   407→    borderWidth: 1,
   408→    borderBottomWidth: 0,
   409→    borderTopLeftRadius: 24,
   410→    borderTopRightRadius: 24,
   411→    paddingHorizontal: 12,
   412→    paddingTop: 12,
   413→    paddingBottom: 24,
   414→  },
   415→  handleIndicator: {
   416→    width: 84,
   417→    height: 4,
   418→    backgroundColor: Colors.white50,
   419→  },
   420→  icon: {
   421→    width: 24,
   422→    height: 24,
   423→  },
   424→});
   425→

