     1→import { Block, Text } from "@prototyp/skeletor";
     2→import { RecoveryState } from "@unomed/react-native-matrix-sdk";
     3→import { SecureStoreKeys } from "modules/matrix-client/models";
     4→import { MatrixService } from "modules/matrix-client/services/matrix-service";
     5→import { NavigationContainerRef } from "modules/navigation/const";
     6→import { type FC, useEffect, useState } from "react";
     7→import { Image, StyleSheet } from "react-native";
     8→import { useMMKVBoolean } from "react-native-mmkv";
     9→import { Button } from "shared/components";
    10→import { Colors, TextSize } from "shared/styles";
    11→
    12→export const ProtectAccountMessage: FC = () => {
    13→  const [hasSeenProtectAccountMessage, setHasSeenProtectAccountMessage] =
    14→    useMMKVBoolean(SecureStoreKeys.HAS_SEEN_PROTECT_ACCOUNT_MESSAGE);
    15→  const [recoveryState, setRecoveryState] = useState<RecoveryState>(
    16→    RecoveryState.Unknown,
    17→  );
    18→  const isOutOfSync = recoveryState === RecoveryState.Incomplete;
    19→
    20→  useEffect(() => {
    21→    const listener = MatrixService.subscribeToRecoveryState((state) => {
    22→      setRecoveryState(state);
    23→    });
    24→
    25→    return () => {
    26→      listener.cancel();
    27→    };
    28→  }, []);
    29→
    30→  const handleProtectAccount = () => {
    31→    NavigationContainerRef.navigate("encryption");
    32→  };
    33→
    34→  const handleEnterRecoveryKey = () => {
    35→    NavigationContainerRef.navigate("enterRecoveryKey");
    36→  };
    37→
    38→  const handleForgotRecoveryKey = () => {
    39→    NavigationContainerRef.navigate("cantConfirm");
    40→  };
    41→
    42→  if (isOutOfSync) {
    43→    return (
    44→      <Block
    45→        margins={{ marginBottom: 20 }}
    46→        paddings={[0, 20]}
    47→        width="100%"
    48→        gap={8}
    49→      >
    50→        <Block flexDirection="row" align="center" width="100%">
    51→          <Image
    52→            height={24}
    53→            width={24}
    54→            source={require("assets/icons/key.png")}
    55→          />
    56→          <Text margins={{ marginLeft: 8 }}>
    57→            Your key storage is out of sync
    58→          </Text>
    59→        </Block>
    60→        <Text size={TextSize.small} color={Colors.white50}>
    61→          Confirm your recovery key to maintain access to your key storage and
    62→          message history.
    63→        </Text>
    64→        <Block gap={12} align="center" width="100%">
    65→          <Button.Secondary
    66→            size="small"
    67→            style={styles.button}
    68→            onPress={handleEnterRecoveryKey}
    69→          >
    70→            Enter Recovery Key
    71→          </Button.Secondary>
    72→          <Button.Wrapper
    73→            style={styles.button}
    74→            onPress={handleForgotRecoveryKey}
    75→          >
    76→            <Block width="100%" align="center">
    77→              <Text size={TextSize.small}>Forgot recovery key?</Text>
    78→            </Block>
    79→          </Button.Wrapper>
    80→        </Block>
    81→      </Block>
    82→    );
    83→  }
    84→
    85→  if (hasSeenProtectAccountMessage) return null;
    86→
    87→  return (
    88→    <Block
    89→      margins={{ marginBottom: 20 }}
    90→      paddings={[0, 20]}
    91→      width="100%"
    92→      gap={8}
    93→    >
    94→      <Block flexDirection="row" align="center" width="100%">
    95→        <Image
    96→          height={24}
    97→          width={24}
    98→          source={require("assets/icons/key.png")}
    99→        />
   100→        <Text margins={{ marginLeft: 8 }}>Protect your account</Text>
   101→        <Button.Wrapper
   102→          style={styles.close}
   103→          onPress={() => setHasSeenProtectAccountMessage(true)}
   104→        >
   105→          <Image
   106→            height={16}
   107→            width={16}
   108→            style={styles.close}
   109→            source={require("assets/icons/close.png")}
   110→          />
   111→        </Button.Wrapper>
   112→      </Block>
   113→      <Text size={TextSize.small} color={Colors.white50}>
   114→        Set up a recovery key so you can restore your encrypted messages if you
   115→        lose access to this device.
   116→      </Text>
   117→      <Button.Secondary size="small" onPress={handleProtectAccount}>
   118→        Set Up
   119→      </Button.Secondary>
   120→    </Block>
   121→  );
   122→};
   123→
   124→const styles = StyleSheet.create({
   125→  close: {
   126→    marginLeft: "auto",
   127→  },
   128→  button: {
   129→    width: "100%",
   130→  },
   131→});
   132→

