     1→import { Block, Text } from "@prototyp/skeletor";
     2→import { useIsFocused } from "@react-navigation/native";
     3→import type { NativeStackScreenProps } from "@react-navigation/native-stack";
     4→import type { UserProfile } from "@unomed/react-native-matrix-sdk";
     5→import { MatrixService } from "modules/matrix-client/services";
     6→import { NavigationContainerRef } from "modules/navigation/const";
     7→import { useEffect, useState } from "react";
     8→import { Image, StyleSheet } from "react-native";
     9→import Toast from "react-native-toast-message";
    10→import {
    11→  Button,
    12→  GoBackHeader,
    13→  Loading,
    14→  ScreenLayout,
    15→  UserImage,
    16→} from "shared/components";
    17→import { Colors, TextSize } from "shared/styles";
    18→import { ActionButtons, BlockUserModal } from "./fragments";
    19→
    20→export const Profile: React.FC<NativeStackScreenProps<Routes, "profile">> = ({
    21→  route,
    22→  navigation,
    23→}) => {
    24→  const { userId } = route.params;
    25→  const isFocused = useIsFocused();
    26→  const [loading, setLoading] = useState(true);
    27→  const [userProfile, setUserProfile] = useState<UserProfile | undefined>(
    28→    undefined,
    29→  );
    30→  const [isVerified, setIsVerified] = useState<boolean>(false);
    31→  const [checkingVerification, setCheckingVerification] = useState(true);
    32→  const [isLoading, setIsLoading] = useState(false);
    33→  const [isBlockUserModalOpen, setIsBlockUserModalOpen] = useState(false);
    34→  const [isUserBlocked, setIsUserBlocked] = useState(false);
    35→
    36→  const handleBlockUser = async () => {
    37→    try {
    38→      setIsLoading(true);
    39→
    40→      if (isUserBlocked) await MatrixService.unblockUser(userId);
    41→      else await MatrixService.blockUser(userId);
    42→
    43→      Toast.show({
    44→        type: "success",
    45→        text1: isUserBlocked
    46→          ? "User unblocked successfully"
    47→          : "User blocked successfully",
    48→      });
    49→
    50→      navigation.goBack();
    51→    } catch (error) {
    52→      console.error(error);
    53→      Toast.show({
    54→        type: "error",
    55→        text1: "Failed to block user",
    56→      });
    57→    } finally {
    58→      setIsLoading(false);
    59→    }
    60→  };
    61→
    62→  const handleConfirmBlockUser = () => {
    63→    setIsBlockUserModalOpen(false);
    64→    handleBlockUser();
    65→  };
    66→
    67→  useEffect(() => {
    68→    if (!isFocused) return;
    69→
    70→    MatrixService.getUserProfile(userId)
    71→      .then(setUserProfile)
    72→      .catch(console.error)
    73→      .finally(() => setLoading(false));
    74→
    75→    MatrixService.isUserVerified(userId)
    76→      .then(setIsVerified)
    77→      .catch(console.error)
    78→      .finally(() => setCheckingVerification(false));
    79→
    80→    MatrixService.isUserBlocked(userId)
    81→      .then(setIsUserBlocked)
    82→      .catch(console.error);
    83→  }, [userId, isFocused]);
    84→
    85→  if (loading || !userProfile) return <Loading />;
    86→
    87→  return (
    88→    <ScreenLayout>
    89→      <Block flex={1} gap={40} scrollable>
    90→        {isLoading && (
    91→          <Loading
    92→            text={isUserBlocked ? "Unblocking user..." : "Blocking user..."}
    93→          />
    94→        )}
    95→        <GoBackHeader margins={{ marginBottom: 40 }} />
    96→        <Block align="center" gap={12}>
    97→          <UserImage
    98→            avatarUrl={userProfile?.avatarUrl}
    99→            displayName={userProfile?.displayName}
   100→            width={120}
   101→            height={120}
   102→            borderRadius={999}
   103→          />
   104→          <Block flexDirection="row" align="center" gap={8}>
   105→            <Text size={TextSize.medium} font="InstrumentSans-Bold">
   106→              {userProfile?.displayName}
   107→            </Text>
   108→            {!checkingVerification && isVerified && (
