import { Block, Text } from "@prototyp/skeletor";
import { RecoveryState } from "@unomed/react-native-matrix-sdk";
import { SecureStoreKeys } from "modules/matrix-client/models";
import { MatrixService } from "modules/matrix-client/services/matrix-service";
import { NavigationContainerRef } from "modules/navigation/const";
import { type FC, useEffect, useState } from "react";
import { Image, StyleSheet } from "react-native";
import { useMMKVBoolean } from "react-native-mmkv";
import { Button } from "shared/components";
import { Colors, TextSize } from "shared/styles";

export const ProtectAccountMessage: FC = () => {
  const [hasSeenProtectAccountMessage, setHasSeenProtectAccountMessage] =
    useMMKVBoolean(SecureStoreKeys.HAS_SEEN_PROTECT_ACCOUNT_MESSAGE);
  const [recoveryState, setRecoveryState] = useState<RecoveryState>(
    RecoveryState.Unknown,
  );
  const isOutOfSync = recoveryState === RecoveryState.Incomplete;

  useEffect(() => {
    const listener = MatrixService.subscribeToRecoveryState((state) => {
      setRecoveryState(state);
    });

    return () => {
      listener.cancel();
    };
  }, []);

  const handleProtectAccount = () => {
    NavigationContainerRef.navigate("encryption");
  };

  const handleEnterRecoveryKey = () => {
    NavigationContainerRef.navigate("enterRecoveryKey");
  };

  const handleForgotRecoveryKey = () => {
    NavigationContainerRef.navigate("cantConfirm");
  };

  if (isOutOfSync) {
    return (
      <Block
        margins={{ marginBottom: 20 }}
        paddings={[0, 20]}
        width="100%"
        gap={8}
      >
        <Block flexDirection="row" align="center" width="100%">
          <Image
            height={24}
            width={24}
            source={require("assets/icons/key.png")}
          />
          <Text margins={{ marginLeft: 8 }}>
            Your key storage is out of sync
          </Text>
        </Block>
        <Text size={TextSize.small} color={Colors.white50}>
          Confirm your recovery key to maintain access to your key storage and
          message history.
        </Text>
        <Block gap={12} align="center" width="100%">
          <Button.Secondary
            size="small"
            style={styles.button}
            onPress={handleEnterRecoveryKey}
          >
            Enter Recovery Key
          </Button.Secondary>
          <Button.Wrapper
            style={styles.button}
            onPress={handleForgotRecoveryKey}
          >
            <Block width="100%" align="center">
              <Text size={TextSize.small}>Forgot recovery key?</Text>
            </Block>
          </Button.Wrapper>
        </Block>
      </Block>
    );
  }

  if (hasSeenProtectAccountMessage) return null;

  return (
    <Block
      margins={{ marginBottom: 20 }}
      paddings={[0, 20]}
      width="100%"
      gap={8}
    >
      <Block flexDirection="row" align="center" width="100%">
        <Image
          height={24}
          width={24}
          source={require("assets/icons/key.png")}
        />
        <Text margins={{ marginLeft: 8 }}>Protect your account</Text>
        <Button.Wrapper
          style={styles.close}
          onPress={() => setHasSeenProtectAccountMessage(true)}
        >
          <Image
            height={16}
            width={16}
            style={styles.close}
            source={require("assets/icons/close.png")}
          />
        </Button.Wrapper>
      </Block>
      <Text size={TextSize.small} color={Colors.white50}>
        Set up a recovery key so you can restore your encrypted messages if you
        lose access to this device.
      </Text>
      <Button.Secondary size="small" onPress={handleProtectAccount}>
        Set Up
      </Button.Secondary>
    </Block>
  );
};

const styles = StyleSheet.create({
  close: {
    marginLeft: "auto",
  },
  button: {
    width: "100%",
  },
});
```

**Key Design Patterns:**
- Two states: normal banner and recovery out-of-sync alert
- Dismissible banner with flag in secure storage (MMKV)
- Key icon with text and action button
- Subscribes to recovery state changes
- Graceful degradation (returns null if dismissed)

