```typescript
import type {
  EventTimelineItem,
  RoomInterface,
  TaskHandleInterface,
  TimelineInterface,
} from "@unomed/react-native-matrix-sdk";
import {
  DateDividerMode,
  MessageType_Tags,
  MsgLikeKind_Tags,
  ReceiptType,
  TimelineDiff_Tags,
  TimelineFilter,
  TimelineFocus,
  TimelineItemContent_Tags,
  TimelineReadReceiptTracking,
} from "@unomed/react-native-matrix-sdk";
import { useSetAtom } from "jotai";
import { MatrixAtoms } from "modules/matrix-client/jotai";
import { MatrixService } from "modules/matrix-client/services";
import { getEventId } from "modules/matrix-client/utils";
import { NavigationContainerRef } from "modules/navigation/const";
import { TimelineAtoms } from "modules/timeline";
import { useCallback, useEffect, useRef, useState } from "react";

/** Maximum age for a verification request to be considered valid (5 minutes) */
const VERIFICATION_REQUEST_MAX_AGE_MS = 5 * 60 * 1000;

/** Check if an event is a verification request */
const isVerificationRequest = (event: EventTimelineItem): boolean => {
  if (event.content.tag !== TimelineItemContent_Tags.MsgLike) return false;
  const kind = event.content.inner.content.kind;
  if (kind?.tag !== MsgLikeKind_Tags.Message) return false;
  const msgType = kind.inner.content.msgType;
  return (
    msgType?.tag === MessageType_Tags.Other &&
    msgType.inner.msgtype === "m.key.verification.request"
  );
};

/** Check if a verification request is recent enough to be handled */
const isRecentVerificationRequest = (event: EventTimelineItem): boolean => {
  const eventTimestamp = Number(event.timestamp);
  const now = Date.now();
  const age = now - eventTimestamp;
  return age < VERIFICATION_REQUEST_MAX_AGE_MS;
};

interface Props {
  room: RoomInterface | undefined;
  roomId: string;
}

export const useRoomTimeline = ({ room, roomId }: Props) => {
  const [events, setEvents] = useState<EventTimelineItem[]>([]);
  const [loadingMessage, setLoadingMessage] = useState(true);
  /** Track processed verification request IDs to avoid duplicates */
  const processedVerificationRequestsRef = useRef<Set<string>>(new Set());
  const [refreshing, setRefreshing] = useState(false);
  const [updateTrigger, setUpdateTrigger] = useState(0);
  const eventIdsRef = useRef<Set<string>>(new Set());
  const timelineRef = useRef<TimelineInterface | null>(null);
  const isPaginatingRef = useRef(false);
  const timelinePaginateNumber = useRef<number>(20);
  const setVerificationStatus = useSetAtom(MatrixAtoms.verificationStatus);
  const setPinnedEventIds = useSetAtom(TimelineAtoms.pinnedEventIds);
  const [isDirect, setIsDirect] = useState(false);

  const upsertEvents = (
    incoming: EventTimelineItem[],
    position: "front" | "back" = "back",
  ) => {
    setEvents((prev) => {
      const next = [...prev];
      for (const e of incoming) {
        const id = getEventId(e);
        if (!id) continue;
        const existingIndex = next.findIndex((item) => getEventId(item) === id);
        if (existingIndex !== -1) {
          next[existingIndex] = e;
          continue;
        }

        eventIdsRef.current.add(id);
        if (position === "front") next.unshift(e);
        else next.push(e);
      }
      return next;
    });
  };

  const handleVerificationRequest = (info: {
    senderId: string;
    flowId: string;
  }) => {
    setVerificationStatus("incomingRequest");
    NavigationContainerRef.navigate("verifyUser", {
      userId: info.senderId,
      flowId: info.flowId,
    });
  };

  const checkForVerificationRequests = useCallback(
    (incoming: EventTimelineItem[]) => {
      for (const event of incoming) {
        if (event.isOwn) continue;

        if (
          !isVerificationRequest(event) ||
          !isRecentVerificationRequest(event)
        ) {
          continue;
        }

        const flowId = getEventId(event);
        if (!flowId) continue;

        if (processedVerificationRequestsRef.current.has(flowId)) continue;

        processedVerificationRequestsRef.current.add(flowId);

        handleVerificationRequest({
          senderId: event.sender,
          flowId,
        });

        // Only handle one at a time
        break;
      }
    },
    [],
  );

  const markAsRead = async () => {
    if (!room) return;

    try {
      await room.markAsRead(ReceiptType.Read);
    } catch (error) {
      console.error("Failed to mark room as read:", error);
    }
  };

  const loadMoreMessages = async () => {
    if (!room || !timelineRef.current) return;

    isPaginatingRef.current = true;
    setRefreshing(true);

    try {
      await timelineRef.current.paginateBackwards(
        timelinePaginateNumber.current,
      );
      timelinePaginateNumber.current += 20;
    } catch (error) {
      console.error("Failed to load more messages:", error);
    } finally {
      setRefreshing(false);
      isPaginatingRef.current = false;
    }
  };

  useEffect(() => {
    if (!room) return;
    setPinnedEventIds([]);
    MatrixService.getPinnedEventIds(roomId)
      .then(setPinnedEventIds)
      .catch(console.error);
  }, [roomId]);

  useEffect(() => {
    if (!room) return;

    // Reset state when room changes
    setEvents([]);
    eventIdsRef.current.clear();

    let timelineListenerHandle: TaskHandleInterface | null = null;

    const initRoomTimeline = async () => {
      try {
        const timeline = await room.timelineWithConfiguration({
          focus: new TimelineFocus.Live({ hideThreadedEvents: false }),
          filter: new TimelineFilter.All(),
          internalIdPrefix: undefined,
          dateDividerMode: DateDividerMode.Daily,
          trackReadReceipts: TimelineReadReceiptTracking.AllEvents,
          reportUtds: false,
        });

        // Store timeline in ref for reuse in pagination
        timelineRef.current = timeline;

        await timeline.paginateBackwards(timelinePaginateNumber.current);
        timelinePaginateNumber.current += 20;
        setLoadingMessage(false);

        // Set up timeline listener for real-time updates
        timelineListenerHandle = await timeline.addListener({
          onUpdate: (diffs) => {
            markAsRead();
            // Trigger re-render to update read receipts and other event properties
            setUpdateTrigger((prev) => prev + 1);
            diffs.forEach((diff) => {
              const change = diff.tag;
              switch (change) {
                case TimelineDiff_Tags.Append: {
                  const newItems = diff.inner.values;
                  if (newItems.length) {
                    const eventItems = newItems
                      .map((i) => i.asEvent())
                      .filter((i): i is EventTimelineItem => !!i);

                    if (eventItems.length > 0) {
                      upsertEvents(eventItems, "back");
                      checkForVerificationRequests(eventItems);
                    }
                  }
                  break;
                }
                case TimelineDiff_Tags.Insert: {
                  const { value } = diff.inner;
                  const ev = value.asEvent();
                  if (ev) {
                    upsertEvents([ev], "back");
                    checkForVerificationRequests([ev]);
                  }
                  break;
                }
                case TimelineDiff_Tags.Set: {
                  const { value } = diff.inner;
                  const ev = value.asEvent();
                  if (ev) {
                    const id = getEventId(ev);
                    if (!id) break;

                    setEvents((prev) => {
                      // Find event by ID to handle edits/deletions properly
                      const existingIndex = prev.findIndex(
                        (e) => getEventId(e) === id,
                      );
                      if (existingIndex !== -1) {
                        const next = [...prev];
                        next[existingIndex] = ev;
                        return next;
                      }
                      // If not found and not tracked, add it
                      if (!eventIdsRef.current.has(id)) {
                        eventIdsRef.current.add(id);
                        return [...prev, ev];
                      }
                      return prev;
                    });
                  }
                  break;
                }
                case TimelineDiff_Tags.Remove: {
                  const { index: removeIndex } = diff.inner;
                  setEvents((prev) => {
                    const next = prev.filter((_, idx) => idx !== removeIndex);
                    eventIdsRef.current = new Set(
                      next.map(getEventId).filter(Boolean) as string[],
                    );
                    return next;
                  });
                  break;
                }
                case TimelineDiff_Tags.PushFront: {
                  const { value } = diff.inner;
                  const ev = value.asEvent();
                  if (ev) {
                    upsertEvents([ev], "front");
                    checkForVerificationRequests([ev]);
                  }
                  break;
                }
                case TimelineDiff_Tags.PushBack: {
                  const { value } = diff.inner;
                  const ev = value.asEvent();
                  if (ev) {
                    upsertEvents([ev], "back");
                    checkForVerificationRequests([ev]);
                  }
                  break;
                }
                case TimelineDiff_Tags.Reset: {
                  const resetItems = diff.inner.values;
                  if (resetItems.length) {
                    const eventItems = resetItems
                      .map((i) => i.asEvent())
                      .filter((i): i is EventTimelineItem => !!i);

                    // Deduplicate events in case Reset contains duplicates
                    const seenIds = new Set<string>();
                    const uniqueEvents: EventTimelineItem[] = [];

                    for (const event of eventItems) {
                      const id = getEventId(event);
                      if (id && !seenIds.has(id)) {
                        seenIds.add(id);
                        uniqueEvents.push(event);
                      }
                    }

                    eventIdsRef.current = seenIds;
                    setEvents(uniqueEvents);
                  }
                  break;
                }
                case TimelineDiff_Tags.Truncate: {
                  const { length: cut } = diff.inner;
                  setEvents((prev) => {
                    const next = prev.slice(0, cut);
                    eventIdsRef.current = new Set(
                      next.map(getEventId).filter(Boolean) as string[],
                    );
                    return next;
                  });
                  break;
                }
                default:
                  console.log("Unknown timeline change type:", change);
              }
            });
          },
        });
      } catch (error) {
        console.error("Failed to initialize room timeline:", error);
        return null;
      }
    };

    initRoomTimeline();

    return () => {
      timelineListenerHandle?.cancel?.();
      timelineRef.current = null;
    };
  }, [roomId, checkForVerificationRequests]);

  useEffect(() => {
    markAsRead().catch(console.error);
    room?.isDirect().then(setIsDirect).catch(console.error);
  }, []);

  return {
    events,
    loadingMessage,
    refreshing,
    timelineRef,
    isPaginatingRef,
    updateTrigger,
    isDirect,
    loadMoreMessages,
    markAsRead,
  };
};
```

**Key Design Patterns:**
- Event deduplication with ID tracking
- Timeline listener with diff-based updates (Append, Insert, Set, Remove, PushFront, PushBack, Reset, Truncate)
- Verification request detection and auto-navigation
- Read receipt tracking
- Pagination with ref management
- Verification request filtering by age (5 minute max)

#### useRoomInitialization.ts (Full Content)

```typescript
import { useIsFocused } from "@react-navigation/native";
import type { RoomInterface } from "@unomed/react-native-matrix-sdk";
import { MembershipState_Tags } from "@unomed/react-native-matrix-sdk";
import { useEffect, useMemo, useState } from "react";

interface UseRoomInitializationProps {
  room: RoomInterface | undefined;
}

export const useRoomInitialization = ({ room }: UseRoomInitializationProps) => {
  const [isEncrypted, setIsEncrypted] = useState(false);
  const [roomMembers, setRoomMembers] = useState(0);
  const isFocused = useIsFocused();
  const [isMembersLoading, setIsMembersLoading] = useState(true);
  const hasNoCallOption = useMemo(() => {
    return (room?.isPublic() && !isEncrypted) || !isEncrypted;
  }, [room, isEncrypted, isFocused]);

  useEffect(() => {
    if (!room) return;

    room.isEncrypted().then(setIsEncrypted).catch(console.error);
    room
      .members()
      .then((info) => {
        const members = info.nextChunk(100) ?? [];
        const acceptedMembers = members.filter(
          (member) => member.membership?.tag === MembershipState_Tags.Join,
        );
        setRoomMembers(acceptedMembers.length);
      })
      .catch(console.error)
      .finally(() => setIsMembersLoading(false));
  }, [room, isFocused]);

  return {
    isMembersLoading,
    isEncrypted,
    roomMembers,
    hasNoCallOption,
  };
};
```

**Key Design Patterns:**
- Encryption state detection
- Member count filtering (Join membership only)
- Call option availability logic
- Focus-aware data loading

